(() => {
  const game = window.DRIFTWING;
  const { ctx, state } = game;
  const challenges = ctx.systems.challenges;
  if (!challenges) throw new Error('challenge step: ctx.systems.challenges is missing');
  const world = ctx.world;
  const dom = (selector) => document.querySelector(selector);
  const kit = {
    results: [],
    events: { started: [], gate: [], finished: [], cancelled: [] },
    baseline: challenges.count(),
    check(name, ok, detail) { const line = `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`; kit.results.push(line); if (!ok) console.error(`[challenge check] ${line}`); return line; },
    hud() {
      const text = (selector) => (dom(selector)?.textContent ?? '').trim();
      const stateOf = (selector) => dom(selector)?.dataset.state ?? null;
      return {
        prompt: stateOf('.dw-challenge-prompt'),
        promptName: text('.dw-challenge-prompt-name'),
        promptDetail: text('.dw-challenge-prompt-detail'),
        promptKey: text('.dw-challenge-prompt-key kbd'),
        timer: stateOf('.dw-challenge-timer'),
        timerPhase: dom('.dw-challenge-timer')?.dataset.phase ?? null,
        time: text('.dw-challenge-time'),
        gates: text('.dw-challenge-gates'),
        penalty: text('.dw-challenge-penalty'),
        splitState: dom('.dw-challenge-split')?.dataset.state ?? null,
        split: text('.dw-challenge-split'),
        flash: dom('.dw-challenge-timer')?.dataset.flash ?? null,
        arrow: stateOf('.dw-challenge-arrow'),
        arrowMode: dom('.dw-challenge-arrow')?.dataset.mode ?? null,
        toast: stateOf('.dw-challenge-toast'),
        toastMedal: dom('.dw-challenge-toast')?.dataset.medal ?? null,
        toastText: text('.dw-challenge-toast'),
      };
    },
    // Removes this course's stored best and path (a fresh profile has none; a rerun starts clean).
    clearRecords() {
      const stored = ctx.storage.read('driftwing-v2.challenges', null);
      if (stored && stored.courses && stored.courses[kit.courseKey]) {
        delete stored.courses[kit.courseKey];
        ctx.storage.write('driftwing-v2.challenges', stored);
      }
      ctx.storage.remove(`driftwing-v2.challengePath.${kit.courseKey}.${state.flight.craft}`);
      challenges.reloadRecords();
    },
    // The course: gates 300 m apart along the craft's heading, 1.2 km ahead, level, well above the ground.
    build(medals) {
      const heading = kit.heading;
      const fx = Math.sin(heading * Math.PI / 180);
      const fz = -Math.cos(heading * Math.PI / 180);
      const roles = ['start', 'checkpoint', 'checkpoint', 'checkpoint', 'finish'];
      let floor = -Infinity;
      for (let along = 0; along <= 1200 + 600; along += 50) floor = Math.max(floor, world.groundHeight(kit.origin.x + fx * along, kit.origin.z + fz * along));
      const y = Math.max(floor, 0) + 220;
      return {
        id: 'stepGauntlet',
        name: 'Step Gauntlet',
        gates: roles.map((role, index) => ({ id: `g${index}`, role, center: { x: kit.origin.x + fx * (600 + index * 300), y, z: kit.origin.z + fz * (600 + index * 300) }, normal: { x: fx, y: 0, z: fz }, up: { x: 0, y: 1, z: 0 }, shape: index === 2 ? 'rect' : 'circle', radius: 30, halfWidth: 34, halfHeight: 22 })),
        medals,
        missed: { mode: 'penalty', penaltySeconds: 5, outsideCrossing: 'miss', skipDistance: 150 },
        start: { mode: 'gate', promptRadius: 1500 },
      };
    },
    // Puts the craft `before` m short of gate `index` on the course line, `side` m to its right, level.
    toGate(index, before, side = 0) {
      const gate = kit.course.gates[index];
      const n = gate.normal;
      const x = gate.center.x - n.x * before - n.z * side;
      const z = gate.center.z - n.z * before + n.x * side;
      ctx.systems.flight.resetTo({ x, y: gate.center.y, z, heading: kit.heading });
    },
    // Resets before each gate in turn and waits for the run to move past it; returns the gate log.
    async fly(gates, before, sideFor = () => 0) {
      const log = [];
      for (const index of gates) {
        kit.toGate(index, before, sideFor(index));
        const started = performance.now();
        const target = index + 1;
        while (performance.now() - started < 20000) {
          await new Promise((done) => setTimeout(done, 50));
          const live = challenges.getState();
          if (index === kit.course.gates.length - 1 ? live.phase === 'finished' : live.phase === 'running' && live.gateIndex >= target) break;
        }
        const live = challenges.getState();
        log.push({ gate: index, phase: live.phase, gateIndex: live.gateIndex, waited: Math.round(performance.now() - started) });
        if (kit.onGate) kit.onGate(index);
      }
      return log;
    },
  };
  kit.heading = state.player.heading;
  kit.origin = { x: state.player.position.x, z: state.player.position.z };
  kit.course = kit.build({ gold: 1, silver: 2, bronze: 900 });
  kit.courseKey = `${state.seed}:stepGauntlet`;
  kit.clearRecords();
  ctx.bus.onTyped('challengeStarted', (payload) => kit.events.started.push(payload));
  ctx.bus.onTyped('challengeGate', (payload) => kit.events.gate.push(payload));
  ctx.bus.onTyped('challengeFinished', (payload) => kit.events.finished.push(payload));
  ctx.bus.onTyped('challengeCancelled', (payload) => kit.events.cancelled.push(payload));
  const key = challenges.register(kit.course, { owner: 'challenge step' });
  window.__challengeKit = kit;
  return `backend ${game.backend}; craft ${state.flight.craft}; course ${key}; courses ${challenges.count()} (baseline ${kit.baseline})`;
})()

